import { ChangeDetectionStrategy, Component, viewChild } from "@angular/core";
import { CardComponent } from "../../lib/card.component";
import { FancyPillComponent } from "../../lib/fancy-pill.component";
import { PillLegacyComponent } from "../../lib/pill-legacy.component";
import { PillComponent, type PillVariant } from "../../lib/pill.component";

@Component({
    selector: "app-feature-8",
    changeDetection: ChangeDetectionStrategy.OnPush,
    imports: [ PillComponent, FancyPillComponent, CardComponent, PillLegacyComponent ],
    templateUrl: "./feature-8.component.html"
})
export class Feature008Component {
    isActive = true;
    count = 1;
    title = "Title 8";
    statusVariant: PillVariant = "warning";

    readonly fancy = viewChild.required(FancyPillComponent);

    describeFancy(): string {
        const fancy = this.fancy();
        return fancy.disableTooltip() ? "quiet" : fancy.label();
    }
}

import { ChangeDetectionStrategy, Component, computed, viewChild } from "@angular/core";
import { CardComponent } from "../../lib/card.component";
import { PillComponent, type PillVariant } from "../../lib/pill.component";

@Component({
    selector: "app-feature-11",
    changeDetection: ChangeDetectionStrategy.OnPush,
    imports: [ PillComponent, CardComponent ],
    templateUrl: "./feature-11.component.html"
})
export class Feature011Component {
    isActive = false;
    count = 4;
    title = "Title 11";
    statusVariant: PillVariant = "success";
    items: { id: number; name: string; variant: PillVariant; hidden: boolean }[] = [ { id: 1, name: "Alpha", variant: "info", hidden: false }, { id: 2, name: "Beta", variant: "warning", hidden: false } ];
    user?: { prefs?: { quiet: boolean } } = { prefs: { quiet: true } };
    flags: Record<string, boolean> = { hidden: false };

    isHidden(): boolean {
        return this.count > 4;
    }

    readonly firstPill = viewChild(PillComponent);
    readonly hintHidden = computed(() => this.firstPill()?.disableTooltip() ?? false);
}

