/** A pill with an icon in front. The label, the variant and the hint switch come from PillComponent. */
@Component({
    selector: "app-fancy-pill",
    changeDetection: ChangeDetectionStrategy.OnPush,
    template: `<span class="pill fancy" [class]="variant()"><i class="icon">{{ icon() }}</i>{{ label() }}@if (!disableTooltip()) {<span class="hint">i</span>}</span>`
})
export class FancyPillComponent extends PillComponent {
    readonly icon = input("star");
}

import { ChangeDetectionStrategy, Component, computed } from "@angular/core";
import { PillComponent } from "./pill.component";

/** A pill for a state of the screen: it reads its label out loud and marks the hint with a question mark. */
@Component({
    selector: "app-status-pill",
    changeDetection: ChangeDetectionStrategy.OnPush,
    template: `<span class="pill status" [class]="variant()" [attr.aria-label]="spoken()">{{ label() }}@if (!disableTooltip()) {<span class="hint">?</span>}</span>`
})
export class StatusPillComponent extends PillComponent {
    readonly spoken = computed(() => this.hideHint() ? this.label() : this.label() + ", a hint is available");
}

import { ChangeDetectionStrategy, Component } from "@angular/core";
import { CardComponent } from "../../lib/card.component";
import { FancyPillComponent } from "../../lib/fancy-pill.component";
import { PillComponent, type PillVariant } from "../../lib/pill.component";

@Component({
    selector: "app-feature-15",
    changeDetection: ChangeDetectionStrategy.OnPush,
    imports: [ PillComponent, FancyPillComponent, CardComponent ],
    template: `
        <app-card
            heading="Feature 15"
            [disableTooltip]="true"
        >
            <!-- disableTooltip above is the card's flag: no hint on the title -->
            <app-pill
                label="Plain"
                variant="warning"
                hideHint
            />
            <app-pill
                [label]="title"
                [variant]="count > 3 ? 'success' : isActive ? 'warning' : 'info'"
                [hideHint]="!(isActive && count > 1)"
            />
            <app-pill [variant]="statusVariant" label="Nested" [hideHint]="false" />
            <app-fancy-pill icon="bolt" label="Fancy" disableTooltip></app-fancy-pill>
        </app-card>
        <app-card #summary heading="Summary" [disableTooltip]="!isActive" />
        <small>Summary hint: {{ summary.hideHint() ? 'off' : 'on' }}</small>
    `
})
export class Feature015Component {
    isActive = false;
    count = 1;
    title = "Title 15";
    statusVariant: PillVariant = "success";
}

